import React, { useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';
import { 
  Package, 
  Truck, 
  Search, 
  CheckCircle, 
  Clock, 
  MapPin, 
  Phone, 
  Mail,
  ChevronRight,
  Star,
  ArrowRight,
  AlertCircle,
  Cloud,
  Navigation,
  Calendar,
  Map,
  Route,
  Settings,
  AlertTriangle,
  Users,
  Brain
} from 'lucide-react';
import * as L from 'leaflet';
import 'leaflet/dist/leaflet.css';

interface OrderStatus {
  id: string;
  status: 'pending' | 'processing' | 'shipped' | 'delivered' | 'cancelled';
  estimatedDelivery: string;
  items: { name: string; quantity: number }[];
  currentLocation: string;
  lastUpdate: string;
  trackingNumber: string;
  customerName: string;
  deliveryAddress: string;
  priority: 'standard' | 'express' | 'premium';
  assignedEmployee?: {
    id: string;
    name: string;
    phone: string;
    currentLocation?: { lat: number; lng: number };
  };
  coordinates: { lat: number; lng: number };
  delayStatus: 'on_time' | 'delayed';
  delayReason?: string;
  weatherImpact: boolean;
  trafficImpact: boolean;
  orderTime: string;
  actualDeliveryTime?: string;
}

interface WeatherData {
  location: string;
  temperature: number;
  condition: string;
  humidity: number;
  windSpeed: number;
  visibility: number;
  icon: string;
}

interface DeliveryPerson {
  id: string;
  name: string;
  phone: string;
  currentLocation: { lat: number; lng: number };
  currentLoad: number;
  maxLoad: number;
  route: string;
  availability: 'available' | 'busy' | 'off_duty';
  efficiency: number;
}

const CustomerPortal: React.FC = () => {
  const [orderId, setOrderId] = useState('');
  const [orderStatus, setOrderStatus] = useState<OrderStatus | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [weather, setWeather] = useState<WeatherData | null>(null);
  const [showRescheduleModal, setShowRescheduleModal] = useState(false);
  const [showAddressModal, setShowAddressModal] = useState(false);
  const [newDeliveryTime, setNewDeliveryTime] = useState('');
  const [newAddress, setNewAddress] = useState({ address: '', coordinates: { lat: 0, lng: 0 } });
  const [actionLoading, setActionLoading] = useState(false);
  const [recommendedDeliveryPeople, setRecommendedDeliveryPeople] = useState<DeliveryPerson[]>([]);
  const mapRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<L.Map | null>(null);

  // Mock recommended delivery people data
  const mockRecommendedDeliveryPeople: DeliveryPerson[] = [
    {
      id: 'EMP004',
      name: 'Suresh Kumar',
      phone: '+91-98765-11111',
      currentLocation: { lat: 28.6200, lng: 77.2000 },
      currentLoad: 2,
      maxLoad: 5,
      route: 'Delhi - Noida - Ghaziabad',
      availability: 'available',
      efficiency: 92
    },
    {
      id: 'EMP005',
      name: 'Anjali Sharma',
      phone: '+91-98765-22222',
      currentLocation: { lat: 28.6000, lng: 77.1800 },
      currentLoad: 1,
      maxLoad: 4,
      route: 'Delhi - Ghaziabad - Noida',
      availability: 'available',
      efficiency: 88
    },
    {
      id: 'EMP006',
      name: 'Rohit Verma',
      phone: '+91-98765-33333',
      currentLocation: { lat: 28.6300, lng: 77.2200 },
      currentLoad: 3,
      maxLoad: 6,
      route: 'Noida - Delhi - Ghaziabad',
      availability: 'busy',
      efficiency: 85
    }
  ];

  // Mock order data for demonstration
  const mockOrders: { [key: string]: OrderStatus } = {
    'ORD12345': {
      id: 'ORD12345',
      status: 'shipped',
      estimatedDelivery: '2024-05-01',
      items: [{ name: 'Premium Package', quantity: 2 }, { name: 'Express Delivery', quantity: 1 }],
      currentLocation: 'Distribution Center, Delhi',
      lastUpdate: '2024-04-26 10:30 AM',
      trackingNumber: 'TRK-78945612',
      customerName: 'Rahul Sharma',
      deliveryAddress: '123 Main Street, Delhi, 110001',
      priority: 'express',
      assignedEmployee: {
        id: 'EMP001',
        name: 'Rajesh Kumar',
        phone: '+91-98765-43210',
        currentLocation: { lat: 28.6139, lng: 77.2090 }
      },
      coordinates: { lat: 28.6139, lng: 77.2090 },
      delayStatus: 'on_time',
      weatherImpact: false,
      trafficImpact: false,
      orderTime: '2024-04-26 09:00 AM',
      actualDeliveryTime: undefined
    },
    'ORD67890': {
      id: 'ORD67890',
      status: 'delivered',
      estimatedDelivery: '2024-04-20',
      items: [{ name: 'Standard Package', quantity: 1 }],
      currentLocation: 'Delivered',
      lastUpdate: '2024-04-20 02:15 PM',
      trackingNumber: 'TRK-45678901',
      customerName: 'Priya Patel',
      deliveryAddress: '456 Park Avenue, Mumbai, 400001',
      priority: 'standard',
      assignedEmployee: {
        id: 'EMP002',
        name: 'Anita Sharma',
        phone: '+91-87654-32109'
      },
      coordinates: { lat: 19.0760, lng: 72.8777 },
      delayStatus: 'on_time',
      weatherImpact: false,
      trafficImpact: false,
      orderTime: '2024-04-20 10:00 AM',
      actualDeliveryTime: '2024-04-20 02:15 PM'
    },
    'ORD11223': {
      id: 'ORD11223',
      status: 'processing',
      estimatedDelivery: '2024-04-28',
      items: [{ name: 'Premium Package', quantity: 1 }, { name: 'Gift Box', quantity: 1 }],
      currentLocation: 'Processing Center',
      lastUpdate: '2024-04-26 09:15 AM',
      trackingNumber: 'TRK-34511223',
      customerName: 'Amit Kumar',
      deliveryAddress: '789 Business Hub, Bangalore, 560001',
      priority: 'premium',
      assignedEmployee: {
        id: 'EMP003',
        name: 'Vikram Singh',
        phone: '+91-76543-21098'
      },
      coordinates: { lat: 12.9716, lng: 77.5946 },
      delayStatus: 'delayed',
      delayReason: 'Heavy traffic in Bangalore area',
      weatherImpact: false,
      trafficImpact: true,
      orderTime: '2024-04-26 08:30 AM',
      actualDeliveryTime: undefined
    }
  };

  const handleTrackOrder = async () => {
    if (!orderId.trim()) {
      setError('Please enter an order ID');
      return;
    }

    setLoading(true);
    setError(null);
    
    // Simulate API call
    setTimeout(() => {
      const foundOrder = mockOrders[orderId.toUpperCase()];
      
      if (foundOrder) {
        setOrderStatus(foundOrder);
        
        // Set recommended delivery people
        setRecommendedDeliveryPeople(mockRecommendedDeliveryPeople);
        
        // Fetch weather if delay is due to weather
        if (foundOrder.weatherImpact) {
          fetchWeather(foundOrder.coordinates.lat, foundOrder.coordinates.lng);
        }
        
        // Initialize professional map
        setTimeout(() => {
          initializeMap();
        }, 100);
      } else {
        setError('Order not found. Please check your order ID and try again.');
      }
      setLoading(false);
    }, 1500);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'pending': return 'text-yellow-600';
      case 'processing': return 'text-blue-600';
      case 'shipped': return 'text-purple-600';
      case 'delivered': return 'text-green-600';
      case 'cancelled': return 'text-red-600';
      default: return 'text-gray-600';
    }
  };

  const getStatusBg = (status: string) => {
    switch (status) {
      case 'pending': return 'bg-yellow-100';
      case 'processing': return 'bg-blue-100';
      case 'shipped': return 'bg-purple-100';
      case 'delivered': return 'bg-green-100';
      case 'cancelled': return 'bg-red-100';
      default: return 'bg-gray-100';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'pending': return Clock;
      case 'processing': return Package;
      case 'shipped': return Truck;
      case 'delivered': return CheckCircle;
      case 'cancelled': return AlertCircle;
      default: return Package;
    }
  };

  // Check 45-minute rule
  const check45MinuteRule = (deliveryTime: string): boolean => {
    const deliveryDate = new Date(deliveryTime);
    const now = new Date();
    const timeDifference = deliveryDate.getTime() - now.getTime();
    const minutesDifference = timeDifference / (1000 * 60);
    return minutesDifference > 45;
  };

  const canPerformActions = orderStatus ? check45MinuteRule(orderStatus.estimatedDelivery) : false;

  // Fetch weather data using OpenWeatherMap API
  const fetchWeather = async (lat: number, lng: number) => {
    try {
      // Replace YOUR_API_KEY with actual OpenWeatherMap API key
      const API_KEY = 'YOUR_OPENWEATHERMAP_API_KEY';
      const response = await fetch(
        `https://api.openweathermap.org/data/2.5/weather?lat=${lat}&lon=${lng}&appid=${API_KEY}&units=metric`
      );
      
      if (!response.ok) {
        throw new Error('Weather API request failed');
      }
      
      const data = await response.json();
      
      const weatherData: WeatherData = {
        location: data.name || 'Unknown Location',
        temperature: Math.round(data.main.temp),
        condition: data.weather[0].description,
        humidity: data.main.humidity,
        windSpeed: Math.round(data.wind.speed * 3.6), // Convert m/s to km/h
        visibility: Math.round(data.visibility / 1000), // Convert m to km
        icon: data.weather[0].icon
      };
      
      setWeather(weatherData);
    } catch (error) {
      console.error('Failed to fetch weather:', error);
      // Fallback to mock data if API fails
      const mockWeather: WeatherData = {
        location: 'Delhi NCR',
        temperature: 28,
        condition: 'Partly Cloudy',
        humidity: 65,
        windSpeed: 12,
        visibility: 8,
        icon: '🌤️'
      };
      setWeather(mockWeather);
    }
  };

  // Fetch route using OSRM API
  const fetchRoute = async (start: { lat: number; lng: number }, end: { lat: number; lng: number }) => {
    try {
      const response = await fetch(
        `https://router.project-osrm.org/route/v1/driving/${start.lng},${start.lat};${end.lng},${end.lat}?overview=full&geometries=geojson&steps=true`
      );
      
      if (!response.ok) {
        throw new Error('Route API request failed');
      }
      
      const data = await response.json();
      return data.routes[0];
    } catch (error) {
      console.error('Failed to fetch route:', error);
      return null;
    }
  };

  // Professional map initialization with Leaflet
  const initializeMap = () => {
    if (!orderStatus || !mapRef.current) return;

    // Clear existing map
    if (mapInstanceRef.current) {
      mapInstanceRef.current.remove();
      mapInstanceRef.current = null;
    }

    const container = mapRef.current;
    container.style.height = '320px';
    container.style.width = '100%';

    // Initialize Leaflet map
    const map = L.map(container, {
      zoomControl: true,
      attributionControl: false
    }).setView([orderStatus.coordinates.lat, orderStatus.coordinates.lng], 13);

    // Add high-quality map tiles
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
      attribution: '© OpenStreetMap contributors'
    }).addTo(map);

    // Custom marker icons
    const createCustomIcon = (emoji: string, color: string, size: number = 30) => {
      return L.divIcon({
        html: `
          <div style="
            background: ${color};
            color: white;
            border-radius: 50%;
            width: ${size}px;
            height: ${size}px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: ${size * 0.5}px;
            font-weight: bold;
            box-shadow: 0 2px 8px rgba(0,0,0,0.3);
            border: 2px solid white;
            z-index: 1000;
          ">${emoji}</div>
        `,
        iconSize: [size, size],
        iconAnchor: [size/2, size/2],
        className: 'custom-marker'
      });
    };

    const deliveryIcon = createCustomIcon('📍', '#10b981', 35);
    const driverIcon = createCustomIcon('🚚', '#3b82f6', 32);

    // Add delivery point marker
    L.marker([orderStatus.coordinates.lat, orderStatus.coordinates.lng], { 
      icon: deliveryIcon,
      zIndex: 1000 
    })
    .addTo(map)
    .bindPopup(`<b>Delivery Location</b><br>${orderStatus.deliveryAddress}`);

    // Add driver and route if available
    if (orderStatus.assignedEmployee?.currentLocation) {
      const driverLoc = orderStatus.assignedEmployee.currentLocation;
      
      // Add driver marker
      L.marker([driverLoc.lat, driverLoc.lng], { 
        icon: driverIcon,
        zIndex: 1000 
      })
      .addTo(map)
      .bindPopup(`<b>Driver: ${orderStatus.assignedEmployee.name}</b><br>📱 ${orderStatus.assignedEmployee.phone}`);

      // Generate realistic route points
      const routePoints = generateRoutePoints(driverLoc, orderStatus.coordinates);
      
      // Create professional route polyline
      const routePolyline = L.polyline(routePoints, {
        color: '#3b82f6',
        weight: 5,
        opacity: 0.8,
        smoothFactor: 1,
        dashArray: null,
        lineCap: 'round',
        lineJoin: 'round',
        className: 'delivery-route'
      }).addTo(map);

      // Add route shadow/glow effect
      L.polyline(routePoints, {
        color: '#1e40af',
        weight: 8,
        opacity: 0.3,
        smoothFactor: 1,
        lineCap: 'round',
        lineJoin: 'round'
      }).addTo(map);

      // Add animated moving dot
      let dotIndex = 0;
      const movingDot = L.circleMarker(routePoints[0], {
        radius: 6,
        fillColor: '#06b6d4',
        color: '#ffffff',
        weight: 2,
        opacity: 1,
        fillOpacity: 1,
        zIndex: 999
      }).addTo(map);

      // Animate the dot
      const animateDot = () => {
        if (dotIndex < routePoints.length - 1) {
          dotIndex++;
          movingDot.setLatLng(routePoints[dotIndex]);
          setTimeout(animateDot, 100);
        } else {
          // Reset animation
          dotIndex = 0;
          setTimeout(animateDot, 2000);
        }
      };
      setTimeout(animateDot, 1000);

      // Fit bounds to show entire route with padding
      const bounds = L.latLngBounds(routePoints);
      map.fitBounds(bounds, { 
        padding: [50, 50],
        maxZoom: 15
      });
    }

    mapInstanceRef.current = map;
  };

  // Generate realistic route points (interpolated path)
  const generateRoutePoints = (start, end) => {
    const points = [];
    const steps = 20; // Number of intermediate points
    
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      
      // Add some curve to make it more realistic
      const curveOffset = Math.sin(t * Math.PI) * 0.01;
      
      const lat = start.lat + (end.lat - start.lat) * t + curveOffset;
      const lng = start.lng + (end.lng - start.lng) * t + curveOffset;
      
      points.push([lat, lng]);
    }
    
    return points;
  };

  // Generate route path description
  const getRoutePath = () => {
    if (!orderStatus?.assignedEmployee?.currentLocation) return 'No route available';
    
    const startLocation = orderStatus.assignedEmployee.currentLocation;
    const endLocation = orderStatus.coordinates;
    
    // Mock route path based on coordinates
    if (orderStatus.id === 'ORD12345') {
      return 'Distribution Center (Delhi) → NH-24 → Ghaziabad Crossing → Raj Nagar → Delivery Point';
    } else if (orderStatus.id === 'ORD67890') {
      return 'Warehouse (Mumbai) → Western Express Highway → Link Road → Park Avenue → Delivered';
    } else if (orderStatus.id === 'ORD11223') {
      return 'Processing Center (Bangalore) → Hosur Road → Electronics City → Silk Board → Business Hub';
    }
    
    return `${startLocation.lat.toFixed(4)}, ${startLocation.lng.toFixed(4)} → ${endLocation.lat.toFixed(4)}, ${endLocation.lng.toFixed(4)}`;
  };

  // Handle customer actions
  const handleRescheduleDelivery = async () => {
    if (!canPerformActions) {
      setError('This action is not possible within 45 minutes of delivery.');
      return;
    }

    setActionLoading(true);
    try {
      // Mock API call - replace with actual API
      setTimeout(() => {
        setShowRescheduleModal(false);
        setNewDeliveryTime('');
        setError('');
        setActionLoading(false);
      }, 1000);
    } catch (error) {
      setError('Failed to reschedule delivery. Please try again.');
      setActionLoading(false);
    }
  };

  const handleUpdateAddress = async () => {
    if (!canPerformActions) {
      setError('This action is not possible within 45 minutes of delivery.');
      return;
    }

    if (!newAddress.address.trim()) {
      setError('Please enter a valid address.');
      return;
    }

    setActionLoading(true);
    try {
      // Mock API call - replace with actual API
      setTimeout(() => {
        setShowAddressModal(false);
        setNewAddress({ address: '', coordinates: { lat: 0, lng: 0 } });
        setError('');
        setActionLoading(false);
      }, 1000);
    } catch (error) {
      setError('Failed to update address. Please try again.');
      setActionLoading(false);
    }
  };
  return (
    <div className="min-h-screen bg-gradient-to-br from-warm-50 via-pink-50 to-orange-50">
      {/* Premium Navigation */}
      <motion.header 
        className="nav-glass shadow-medium fixed top-0 left-0 right-0 z-50"
        initial={{ y: -100 }}
        animate={{ y: 0 }}
        transition={{ duration: 0.6 }}
      >
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16 lg:h-20">
            <motion.div 
              className="flex items-center space-x-3"
              whileHover={{ scale: 1.05 }}
              transition={{ duration: 0.2 }}
            >
              <div className="w-10 h-10 bg-gradient-to-br from-primary-600 to-secondary-600 rounded-xl flex items-center justify-center">
                <Truck className="w-6 h-6 text-white" />
              </div>
              <span className="text-xl lg:text-2xl font-bold text-gray-800">
                Customer Portal
              </span>
            </motion.div>

            <nav className="hidden md:flex items-center space-x-8">
              {['Home', 'Customer Portal', 'Employee Portal'].map((item, index) => (
                <motion.div
                  key={item}
                  initial={{ opacity: 0, y: -20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: index * 0.1 }}
                >
                  <Link 
                    to={item === 'Home' ? '/' : item === 'Customer Portal' ? '/customer' : '/employee'}
                    className="relative text-gray-700 hover:text-primary-600 font-medium transition-colors duration-200 group"
                  >
                    {item}
                    <span className="absolute -bottom-1 left-0 w-0 h-0.5 bg-gradient-to-r from-primary-600 to-secondary-600 group-hover:w-full transition-all duration-300"></span>
                  </Link>
                </motion.div>
              ))}
            </nav>

            <motion.div 
              className="flex items-center space-x-4"
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: 0.5 }}
            >
              <motion.div whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}>
                <Link 
                  to="/"
                  className="premium-button-secondary text-sm px-6 py-2.5"
                >
                  Back to Home
                </Link>
              </motion.div>
            </motion.div>
          </div>
        </div>
      </motion.header>

      {/* Hero Section */}
      <section className="relative min-h-screen flex items-center justify-center overflow-hidden pt-20">
        {/* Professional Background with Color Transition */}
        <div className="absolute inset-0">
          <div className="absolute inset-0 hero-gradient-bg opacity-20 animate-gradient"></div>
          <div className="absolute inset-0">
            <div className="absolute top-0 left-0 w-96 h-96 bg-primary-200/30 rounded-full blur-3xl animate-pulse-slow"></div>
            <div className="absolute top-0 right-0 w-96 h-96 bg-secondary-200/30 rounded-full blur-3xl animate-pulse-slow" style={{ animationDelay: '2s' }}></div>
            <div className="absolute bottom-0 left-1/2 w-96 h-96 bg-accent-200/30 rounded-full blur-3xl animate-pulse-slow transform -translate-x-1/2" style={{ animationDelay: '4s' }}></div>
          </div>
        </div>

        <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
          <div className="relative z-10 bg-white/85 backdrop-blur-md rounded-3xl p-8 lg:p-12 shadow-large border border-white/50">
            <motion.div
              initial={{ opacity: 0, y: 30 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.8 }}
            >
              <motion.div 
                className="inline-flex items-center px-4 py-2 bg-white/80 backdrop-blur-sm border border-white/50 rounded-full shadow-soft mb-6"
                whileHover={{ scale: 1.05 }}
              >
                <Search className="w-4 h-4 text-primary-600 mr-2" />
                <span className="text-sm font-medium text-gray-700">Track Your Order Instantly</span>
              </motion.div>

              <h1 className="text-5xl md:text-7xl font-bold mb-6">
                <span className="block text-gray-900 mb-2">Track Your</span>
                <span className="block text-gray-800">Package</span>
              </h1>

              <motion.p 
                className="text-xl md:text-2xl text-gray-700 mb-8 max-w-3xl mx-auto leading-relaxed font-medium"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.3, duration: 0.6 }}
              >
                Enter your order ID to get real-time tracking information and delivery updates
              </motion.p>

              {/* Order Tracking Form */}
              <motion.div 
                className="max-w-md mx-auto mb-8"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.5, duration: 0.6 }}
              >
                <div className="flex flex-col sm:flex-row gap-4">
                  <input
                    type="text"
                    placeholder="Enter Order ID (e.g., ORD12345)"
                    value={orderId}
                    onChange={(e) => setOrderId(e.target.value)}
                    onKeyPress={(e) => e.key === 'Enter' && handleTrackOrder()}
                    className="flex-1 px-4 py-3 bg-white/80 backdrop-blur-sm border border-gray-300 rounded-xl focus:outline-none focus:border-primary-500 text-gray-800 placeholder-gray-500 shadow-soft"
                  />
                  <motion.button
                    onClick={handleTrackOrder}
                    disabled={loading}
                    whileHover={{ scale: loading ? 1 : 1.05 }}
                    whileTap={{ scale: loading ? 1 : 0.95 }}
                    className="premium-button px-8 py-3 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {loading ? (
                      <div className="flex items-center">
                        <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white mr-2"></div>
                        Tracking...
                      </div>
                    ) : (
                      <div className="flex items-center">
                        <Search className="w-5 h-5 mr-2" />
                        Track Order
                      </div>
                    )}
                  </motion.button>
                </div>

                {error && (
                  <motion.div
                    initial={{ opacity: 0, y: -10 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="mt-4 p-3 bg-red-100 border border-red-200 rounded-xl text-red-700 flex items-center"
                  >
                    <AlertCircle className="w-5 h-5 mr-2" />
                    {error}
                  </motion.div>
                )}

                <div className="mt-6 text-sm text-gray-600">
                  <p className="mb-2">Try these sample order IDs:</p>
                  <div className="flex flex-wrap gap-2 justify-center">
                    {['ORD12345', 'ORD67890', 'ORD11223'].map((id) => (
                      <button
                        key={id}
                        onClick={() => setOrderId(id)}
                        className="px-3 py-1 bg-primary-100 text-primary-700 rounded-lg hover:bg-primary-200 transition-colors text-xs font-medium"
                      >
                        {id}
                      </button>
                    ))}
                  </div>
                </div>
              </motion.div>
            </motion.div>
          </div>
        </div>
      </section>

      {/* Order Status Results */}
      {orderStatus && (
        <motion.section
          className="py-20 lg:py-32"
          initial={{ opacity: 0 }}
