            transition={{ duration: 0.3 }}
          >
            <h3 className="text-xl font-semibold text-gray-900 mb-4">Reschedule Delivery</h3>
            <p className="text-gray-600 mb-6">Select a new delivery time for your order.</p>
            
            <input
              type="datetime-local"
              value={newDeliveryTime}
              onChange={(e) => setNewDeliveryTime(e.target.value)}
              className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent mb-6"
            />
            
            <div className="flex justify-end space-x-4">
              <button
                onClick={() => setShowRescheduleModal(false)}
                className="px-6 py-2 text-gray-600 hover:text-gray-900 font-medium"
              >
                Cancel
              </button>
              <button
                onClick={handleRescheduleDelivery}
                disabled={actionLoading}
                className="premium-button px-6 py-2 disabled:opacity-50"
              >
                {actionLoading ? 'Updating...' : 'Update'}
              </button>
            </div>
          </motion.div>
        </motion.div>
      )}

      {showAddressModal && (
        <motion.div
          className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
        >
          <motion.div
            className="bg-white rounded-2xl p-8 w-full max-w-md"
            initial={{ scale: 0.9, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            transition={{ duration: 0.3 }}
          >
            <h3 className="text-xl font-semibold text-gray-900 mb-4">Update Delivery Address</h3>
            <p className="text-gray-600 mb-6">Enter your new delivery address.</p>
            
            <input
              type="text"
              placeholder="Enter new address"
              value={newAddress.address}
              onChange={(e) => setNewAddress({ ...newAddress, address: e.target.value })}
              className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent mb-6"
            />
            
            <div className="flex justify-end space-x-4">
              <button
                onClick={() => setShowAddressModal(false)}
                className="px-6 py-2 text-gray-600 hover:text-gray-900 font-medium"
              >
                Cancel
              </button>
              <button
                onClick={handleUpdateAddress}
                disabled={actionLoading}
                className="premium-button px-6 py-2 disabled:opacity-50"
              >
                {actionLoading ? 'Updating...' : 'Update'}
              </button>
            </div>
          </motion.div>
        </motion.div>
      )}
    </div>
  );
};

export default CustomerPortal;
